verdicts.after:
const ghost = page.getByTestId('open-file-button');
await ghost.hover();
// NOT "differs from its own resting value" — measured on 1.61.1: Tailwind's preflight paints every
// <button> `background-color: transparent`, so resting is rgba(0, 0, 0, 0) and ANY opaque hover
// differs from it. hover:bg-muted (the regression this shot exists for) and hover:bg-rail (Step 4's
// sabotage) BOTH pass that form. Compare against --elevate itself, resolved through the SAME
// serializer as the button's own computed value: a throwaway element, not
// getPropertyValue('--elevate'), which returns the authored `oklch(93.5% 0.006 240.4deg)` where the
// computed value reads `oklch(0.935 0.006 240.4)` — a format mismatch is exactly the failure the
// Task 5 helper's doc-comment warns about.
const elevate = await page.evaluate(() => {
  const probe = document.createElement('div');
  probe.style.backgroundColor = 'var(--elevate)';
  document.body.append(probe);
  const value = globalThis.getComputedStyle(probe).backgroundColor;
  probe.remove();
  return value;
});
await expect
  .poll(() => ghost.evaluate((el) => globalThis.getComputedStyle(el).backgroundColor))
  .toBe(elevate);

